using System;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Windows.Forms;
namespace RcsMap {
 public static class WorkspaceTests {
  static int count;static readonly BindingFlags Flags=BindingFlags.Instance|BindingFlags.NonPublic;
  static void Check(bool value,string text){if(!value)throw new Exception("workspace failed: "+text);count++;}
  static T Field<T>(Editor e,string name){return (T)typeof(Editor).GetField(name,Flags).GetValue(e);}
  static object Call(Editor e,string name,params object[] args){return typeof(Editor).GetMethod(name,Flags).Invoke(e,args);}
  static MapDocument Doc(Editor e){return Field<MapDocument>(e,"doc");}
  static void Mouse(MapCanvas canvas,string method,Point p,MouseButtons button=MouseButtons.Left){typeof(MapCanvas).GetMethod(method,Flags).Invoke(canvas,new object[]{new MouseEventArgs(button,1,p.X,p.Y,0)});}
  static Point At(MapCanvas c,double x,double y){return Point.Round(c.ScreenPoint(x,y));}
  static void Throws(Action action,string name){bool thrown=false;try{action();}catch{thrown=true;}Check(thrown,name);}
  public static void Run(string folder){Directory.CreateDirectory(folder);var initial=TerrainGeometry.Demo();initial.Points.RemoveAt(2);initial.Points.RemoveAt(1);initial.Terrain.Connections.Clear();string original=initial.Json();string file=Path.Combine(Path.GetFullPath(folder),"unfinished.rcsmap.json");File.WriteAllText(file,original);
   using(var editor=new Editor()){editor.ShowInTaskbar=false;editor.Opacity=0;editor.Show();Application.DoEvents();editor.OpenRecovery(file);Application.DoEvents();var canvas=Field<MapCanvas>(editor,"canvas");var panel=Field<TerrainTools>(editor,"terrainTools");var tabs=Field<TabControl>(editor,"viewTabs");var left=Field<TabControl>(editor,"leftTabs");var grid=Field<DataGridView>(editor,"points");var picker=Field<ComboBox>(editor,"surfacePicker");
    Check(left.TabPages.Cast<TabPage>().Select(page=>page.Text).SequenceEqual(new[]{"底盘参数","平台/坡道","连接"}),"terrain entrances are main-window tabs");Check(tabs.TabPages[0].Text=="俯视编辑"&&tabs.TabPages[1].Text=="路线侧视"&&tabs.TabPages[2].Text=="三维预览","three persistent views");
    Call(editor,"EditTerrain");Check(Application.OpenForms.Count==1,"terrain entry does not open modal form");Check(Doc(editor).Json()==original,"opening terrain panel does not clone/commit a map");
    Call(editor,"SetMode",0);canvas.Fit();Point other=At(canvas,5000,2500);Mouse(canvas,"OnMouseDown",other);Mouse(canvas,"OnMouseUp",other);Check(canvas.Selected==1&&canvas.ActiveSurfaceId==Doc(editor).Points[1].SurfaceId,"clicking visible other-layer point selects it and switches layer");
    string ramp=Doc(editor).Terrain.Surfaces[0].Id,deck=Doc(editor).Terrain.Surfaces[1].Id;string first=Doc(editor).Points[0].Id,last=Doc(editor).Points[1].Id;
    Call(editor,"SelectPoint",0);picker.SelectedIndex=picker.Items.Cast<SurfaceChoice>().ToList().FindIndex(c=>c.Id==ramp);Check(canvas.Selected==0,"switching current layer preserves insertion anchor");Call(editor,"SetMode",1);canvas.Fit();Point p=At(canvas,2400,2500);Mouse(canvas,"OnMouseDown",p);Mouse(canvas,"OnMouseUp",p);Check(Doc(editor).Points.Count==3&&Doc(editor).Points[0].Id==first&&Doc(editor).Points[2].Id==last,"point inserted between existing stable IDs");var inserted=Doc(editor).Points[1];string insertedId=inserted.Id;Check(inserted.SurfaceId==ramp&&inserted.CorrectionMode==0&&inserted.ArrivalActions.Count==0&&inserted.DepartureActions.Count==0,"new slope point has correct surface and no correction/actions");Check(Math.Abs(TerrainGeometry.Height(Doc(editor),inserted)-150)<20,"new point height derived from slope");
    var profile=Field<TerrainCanvas>(editor,"profileView");var three=Field<TerrainCanvas>(editor,"threeView");Check(Object.ReferenceEquals(canvas.Document,profile.Document)&&Object.ReferenceEquals(profile.Document,three.Document)&&Object.ReferenceEquals(profile.Document,Doc(editor)),"all views share one document after insertion");
    tabs.SelectedIndex=2;grid.CurrentCell=grid.Rows[1].Cells[0];Call(editor,"SelectPoint",1);Check(three.SelectedPoint==1&&profile.SelectedPoint==1,"selection shared across views");tabs.SelectedIndex=0;grid.Rows[1].Cells[1].Value=deck;Check(Doc(editor).Points[1].SurfaceId==deck&&grid.Rows[1].Cells[2].Value.ToString()=="500","surface assignment updates derived Z in table");Call(editor,"Undo");Check(Doc(editor).Points[1].SurfaceId==ramp,"surface assignment is globally undoable");Call(editor,"Redo");Check(Doc(editor).Points[1].SurfaceId==deck,"surface assignment redo");Call(editor,"Undo");
    Call(editor,"Undo");Check(Doc(editor).Points.Count==2,"global undo removes inserted point");Check(Object.ReferenceEquals(profile.Document,Doc(editor))&&Object.ReferenceEquals(three.Document,Doc(editor)),"undo rebinds both geometry views");Call(editor,"Redo");Check(Doc(editor).Points[1].Id==insertedId,"redo retains inserted stable ID");
    panel=Field<TerrainTools>(editor,"terrainTools");int surfaces=Doc(editor).Terrain.Surfaces.Count;panel.AddSurface(false);Check(Doc(editor).Terrain.Surfaces.Count==surfaces+1,"add platform without a dialog");Call(editor,"Undo");Check(Doc(editor).Terrain.Surfaces.Count==surfaces,"platform creation uses same global undo");Call(editor,"Redo");Check(Doc(editor).Terrain.Surfaces.Count==surfaces+1,"platform redo");Call(editor,"Undo");
    panel.Connect(TerrainGeometry.Ground,deck);Check(Doc(editor).Terrain.Connections.Any(c=>TerrainGeometry.Key(c.A)==TerrainGeometry.Ground&&c.B==deck),"unjoined but structurally valid connection may be drafted");Check(Doc(editor).Validate().Any(x=>x.Contains("接合边")),"draft connection is not falsely validated");Call(editor,"Undo");Check(Doc(editor).Terrain.Connections.Count==0,"connection undo shares history");
    Call(editor,"SetActiveSurface",ramp);Call(editor,"SetMode",4);canvas.Fit();string before=Doc(editor).Json();p=At(canvas,2000,2100);Point q=At(canvas,2200,2200);Mouse(canvas,"OnMouseDown",p);Mouse(canvas,"OnMouseMove",q);Check(Doc(editor).Json()!=before,"main canvas drags surface");canvas.CancelInteraction();Check(Doc(editor).Json()==before,"main drag cancellation restores whole shared document");
    canvas.Fit();p=At(canvas,2000,2100);q=At(canvas,2200,2200);Mouse(canvas,"OnMouseDown",p);Mouse(canvas,"OnMouseMove",q);Mouse(canvas,"OnMouseUp",q);Check(Doc(editor).Json()!=before,"main surface drag commits");Call(editor,"Undo");Check(Doc(editor).Json()==before,"main surface drag is a single global undo");Check(Object.ReferenceEquals(profile.Document,Doc(editor)),"drag undo refreshes shared references");
    panel.Connect(TerrainGeometry.Ground,ramp);panel.Connect(ramp,deck);Check(Doc(editor).Validate().Count==0,"adding transition point and correct links completes real route: "+String.Join(" / ",Doc(editor).Validate().ToArray()));Call(editor,"Undo");Call(editor,"Undo");Check(Doc(editor).Terrain.Connections.Count==0,"undo completed-route links restores unfinished draft");
    Call(editor,"SelectPoint",1);var inspector=Field<PropertyGrid>(editor,"pointProperties").SelectedObject;Check(Object.ReferenceEquals(typeof(PointInspector).GetField("point",Flags).GetValue(inspector),Doc(editor).Points[1]),"point property inspector rebinds after global history");
    string save=Path.Combine(Path.GetFullPath(folder),"shared-draft.rcsmap.json");typeof(Editor).GetField("filename",Flags).SetValue(editor,save);Check((bool)Call(editor,"Save",false),"unconnected map saves without modal validation gate");string saved=File.ReadAllText(save);Check(MapDocument.Parse(saved).Json()==Doc(editor).Json(),"draft round trip preserves all edits");Check(Doc(editor).Validate().Count>0,"saving draft does not mark route valid");
    string output=Path.Combine(Path.GetFullPath(folder),"rejected-export");Directory.CreateDirectory(output);File.WriteAllText(Path.Combine(output,"sentinel"),"keep");Throws(()=>Exporter.Export(Doc(editor),output),"nonplanar draft export still rejected");Check(Directory.GetFiles(output).Length==1&&File.ReadAllText(Path.Combine(output,"sentinel"))=="keep","rejected export does not change output");
    var flat=MapDocument.Demo();flat.Obstacles.Add(new Obstacle(500,500,1000,1000));DraftRules.Check(flat);Check(flat.Validate().Count>0,"invalid flat geometry can also be a draft");var bad=Doc(editor).Clone();bad.Points[0].X=Double.NaN;Throws(()=>DraftRules.Check(bad),"nonfinite geometry cannot enter draft editor");
    editor.Size=new Size(1120,800);Application.DoEvents();canvas.Fit();Call(editor,"SelectPoint",1);using(var bitmap=new Bitmap(editor.Width,editor.Height)){editor.DrawToBitmap(bitmap,new Rectangle(0,0,editor.Width,editor.Height));bitmap.Save(Path.Combine(folder,"workspace-minimum.png"));}Check(canvas.Width>=440&&canvas.Height>=380,"minimum window retains editable canvas");Check(Field<ComboBox>(editor,"surfacePicker").Visible&&panel.SurfacePage.Parent==left,"main controls remain exposed at minimum size");
    typeof(Editor).GetField("savedJson",Flags).SetValue(editor,Doc(editor).Json());editor.Close();
   }
   using(var reopened=new Editor()){reopened.OpenRecovery(Path.Combine(Path.GetFullPath(folder),"shared-draft.rcsmap.json"));Check(Doc(reopened).Validate().Count>0&&Doc(reopened).Points.Count==3,"reopen unfinished map without losing points");}
   File.WriteAllText(Path.Combine(folder,"workspace-selftest.txt"),"PASS "+count+" shared-workspace checks\n");Console.WriteLine("PASS "+count+" shared-workspace checks");
  }
 }
}
